128	  /// 解析名称、点列、以及文件内可信的起止时间。
129	  static GpxSummary parse(String xml) {
130	    var name = '';
131	    final m = _nameRe.firstMatch(xml);
132	    if (m != null) {
133	      name = m.group(1)!.trim();
134	    }
135	
136	    final raw = _extractPts(xml);
137	    final points = [for (final p in raw) p.ll];
138	    final km = distanceKm(points);
139	    final times = plausibleTimes(xml);
140	    final start = times.isEmpty ? null : times.first;
141	    final end = times.isEmpty ? null : times.last;
142	    Duration? duration;
143	    if (start != null && end != null) {
144	      final d = end.difference(start);
145	      if (d.inSeconds >= 15) duration = d;
146	    }
147	    final speeds = _speedSeries(raw);
148	    final hr = _hrSeries(raw);
149	    final cad = _cadSeries(raw);
150	    final pw = _powerSeries(raw);
151	    final elev = _elev(raw);
152	    var gain = elev.gain;
153	    final extClimb = _extClimbRe.firstMatch(xml);
154	    if (gain == null && extClimb != null) {
155	      final v = double.tryParse(extClimb.group(1)!);
156	      if (v != null && v > 0.5) gain = v;
157	    }
158	    double? avg;
159	    if (duration != null && km > 0.05) {
160	      final hours = duration.inMilliseconds / 3600000.0;
161	      if (hours > 0) avg = km / hours;
162	    }
163	    if (avg == null && speeds.points.isNotEmpty) {
164	      var s = 0.0;
165	      for (final p in speeds.points) {
166	        s += p.value;
167	      }
168	      avg = s / speeds.points.length;
169	    }
170	    var atPoint = speeds.atPoint;
171	    if (avg != null && avg > 0 && atPoint.length > 1) {
172	      var any = false;
173	      for (final v in atPoint) {
174	        if (v > 0.2) {
175	          any = true;
176	          break;
177	        }
178	      }
179	      if (!any) {
180	        atPoint = List<double>.filled(atPoint.length, avg);
181	        atPoint[0] = 0;
182	      }
183	    }
184	    return GpxSummary(
185	      name: name,
186	      points: points,
187	      distanceKm: km,
188	      startTime: start,
189	      endTime: end,
190	      duration: duration,
191	      avgSpeedKmh: avg,
192	      maxSpeedKmh: speeds.max,
193	      elevGainM: gain,
194	      elevLossM: elev.loss,
195	      minEleM: elev.min,
196	      maxEleM: elev.max,
197	      avgHrBpm: hr.avg,
198	      maxHrBpm: hr.max,
199	      hrPoints: hr.points,
200	      avgCadenceRpm: cad.avg,
201	      maxCadenceRpm: cad.max,
202	      cadPoints: cad.points,
203	      avgPowerW: pw.avg,
204	      maxPowerW: pw.max,
205	      powerPoints: pw.points,
206	      pointCadenceRpm: [for (final p in raw) p.cad],
207	      pointPowerW: [for (final p in raw) p.pw],
208	      pointHrBpm: [for (final p in raw) p.hr],
209	      speedPoints: speeds.points,
210	      pointSpeedsKmh: speeds.atPoint,
211	    );
212	  }
