214	  static List<_GpxPt> _extractPts(String xml) {
215	    final out = <_GpxPt>[];
216	    for (final match in _openPtRe.allMatches(xml)) {
217	      final ll = _llFromAttrs(match.group(1)!);
218	      if (ll == null) continue;
219	      final inner = match.group(2)!;
220	      final eleM = _eleRe.firstMatch(inner);
221	      final timeM = _timeRe.firstMatch(inner);
222	      DateTime? t;
223	      if (timeM != null) {
224	        t = tryParseUtc(timeM.group(1)!);
225	        if (t != null && !isPlausibleTime(t)) t = null;
226	      }
227	      out.add((
228	        ll: ll,
229	        ele: eleM == null ? null : double.tryParse(eleM.group(1)!),
230	        time: t,
231	        hr: _hrFromInner(inner),
232	        cad: _cadFromInner(inner),
233	        pw: _powerFromInner(inner),
234	        spdMps: _speedFromInner(inner),
235	      ));
236	    }
237	    if (out.isNotEmpty) return out;
238	    for (final match in _ptRe.allMatches(xml)) {
239	      final lat = double.tryParse(match.group(1)!);
240	      final lon = double.tryParse(match.group(2)!);
241	      if (lat != null && lon != null) {
242	        out.add((
243	          ll: LatLng(lat, lon),
244	          ele: null,
245	          time: null,
246	          hr: null,
247	          cad: null,
248	          pw: null,
249	          spdMps: null,
250	        ));
251	      }
252	    }
253	    if (out.isNotEmpty) return out;
254	    for (final match in _ptReSwap.allMatches(xml)) {
255	      final lon = double.tryParse(match.group(1)!);
256	      final lat = double.tryParse(match.group(2)!);
257	      if (lat != null && lon != null) {
258	        out.add((
259	          ll: LatLng(lat, lon),
260	          ele: null,
261	          time: null,
262	          hr: null,
263	          cad: null,
264	          pw: null,
265	          spdMps: null,
266	        ));
267	      }
268	    }
269	    return out;
270	  }
