304	  static LatLng? _llFromAttrs(String attrs) {
305	    final lat = double.tryParse(_latAttrRe.firstMatch(attrs)?.group(1) ?? '');
306	    final lon = double.tryParse(_lonAttrRe.firstMatch(attrs)?.group(1) ?? '');
307	    if (lat == null || lon == null) return null;
