311	  /// 逐点速度。优先用码表记录的设备速度（m/s → km/h），没有才用相邻点
312	  /// 距离 / 时间差推算；都缺时沿用上一个值（第 0 点为 0）。
313	  static ({double? max, List<RideSeriesPoint> points, List<double> atPoint})
314	      _speedSeries(List<_GpxPt> pts) {
315	    var maxV = 0.0;
316	    final series = <RideSeriesPoint>[];
317	    final atPoint = List<double>.filled(pts.length, 0);
318	    var last = 0.0;
319	    for (var i = 0; i < pts.length; i++) {
320	      var v = last;
321	      final dev = pts[i].spdMps;
322	      if (dev != null) {
323	        // 设备速度不受 0.8~60 s 时间窗限制（GNSS 丢点时照样可信）。
324	        v = dev * 3.6;
325	        series.add(RideSeriesPoint(time: pts[i].time, value: v));
326	        if (v > maxV) maxV = v;
327	      } else if (i > 0) {
328	        final a = pts[i - 1].time;
329	        final b = pts[i].time;
330	        if (a != null && b != null) {
331	          final sec = b.difference(a).inMilliseconds / 1000.0;
332	          if (sec >= 0.8 && sec <= 60) {
333	            final km = _haversineKm(pts[i - 1].ll, pts[i].ll);
334	            final raw = km / (sec / 3600.0);
335	            if (raw > 0 && raw < 80) {
336	              v = raw;
337	              series.add(RideSeriesPoint(time: b, value: v));
338	              if (v > maxV) maxV = v;
339	            }
340	          }
341	        }
342	      }
343	      atPoint[i] = v;
344	      last = v;
345	    }
346	    return (
347	      max: maxV > 0.5 ? maxV : null,
348	      points: series,
349	      atPoint: atPoint,
350	    );
351	  }
