353	  /// 沿轨迹每整公里一个点。
354	  ///
355	  /// [at] 是它落在轨迹上的位置，用「点下标」表示（`4.5` = 第 4、5 点之间）。回放时
356	  /// 用它判断线画到没有 —— 缺了它就只能猜，牌子要么全出来要么全不出来。
357	  static List<({LatLng ll, int km, double at})> kmMarkers(
358	    List<LatLng> points, {
359	    double intervalKm = 1,
360	    int maxMarks = 120,
361	  }) {
362	    final out = <({LatLng ll, int km, double at})>[];
363	    if (points.length < 2 || intervalKm <= 0) return out;
364	    var acc = 0.0;
365	    var next = intervalKm;
366	    var n = 1;
367	    for (var i = 1; i < points.length; i++) {
368	      final d = _haversineKm(points[i - 1], points[i]);
369	      if (d <= 0) continue;
370	      while (acc + d >= next && n <= maxMarks) {
371	        final t = ((next - acc) / d).clamp(0.0, 1.0);
372	        final a = points[i - 1];
373	        final b = points[i];
374	        out.add((
375	          ll: LatLng(
376	            a.latitude + (b.latitude - a.latitude) * t,
377	            a.longitude + (b.longitude - a.longitude) * t,
378	          ),
379	          km: n,
380	          at: (i - 1) + t,
381	        ));
382	        n++;
383	        next += intervalKm;
384	      }
385	      acc += d;
386	    }
387	    return out;
388	  }
389	
390	  /// 每个点的累计骑行时间（秒，从 0 起）。
391	  ///
392	  /// 用相邻两点的距离除以该点速度累加，还原「这段路实际花了多久」，回放时才能
393	  /// 按运动本身的速度推进（快的地方画得快）。比按点数平均更贴近真实节奏。
394	  /// 速度缺失或异常（<=0.2 km/h）时用 [fallbackKmh] 兜底。
395	  static List<double> cumulativeRideSeconds(
396	    List<LatLng> points,
397	    List<double> speedsAtPoint, {
398	    double fallbackKmh = 18,
399	  }) {
400	    final n = points.length;
401	    final out = List<double>.filled(n, 0);
402	    if (n < 2) return out;
403	    var acc = 0.0;
404	    for (var i = 1; i < n; i++) {
405	      final d = _haversineKm(points[i - 1], points[i]);
406	      var v = i < speedsAtPoint.length ? speedsAtPoint[i] : fallbackKmh;
407	      if (!(v > 0.2)) v = fallbackKmh;
408	      acc += d / v * 3600.0;
409	      out[i] = acc;
410	    }
411	    return out;
412	  }
