414	  static ({int? avg, int? max, List<RideSeriesPoint> points}) _hrSeries(
415	    List<_GpxPt> pts,
416	  ) {
417	    final series = <RideSeriesPoint>[];
418	    var sum = 0;
419	    var maxV = 0;
420	    for (final p in pts) {
421	      final hr = p.hr;
422	      if (hr == null) continue;
423	      series.add(RideSeriesPoint(time: p.time, value: hr.toDouble()));
424	      sum += hr;
425	      if (hr > maxV) maxV = hr;
426	    }
427	    if (series.isEmpty) {
428	      return (avg: null, max: null, points: const []);
429	    }
430	    return (
431	      avg: (sum / series.length).round(),
432	      max: maxV,
433	      points: series,
434	    );
435	  }
