437	  /// 踏频序列与统计。`0` 是「在滑行」，算有效样本但不进平均。
438	  static ({int? avg, int? max, List<RideSeriesPoint> points}) _cadSeries(
439	    List<_GpxPt> pts,
440	  ) {
441	    final series = <RideSeriesPoint>[];
442	    var sum = 0;
443	    var n = 0;
444	    var maxV = 0;
445	    for (final p in pts) {
446	      final cad = p.cad;
447	      if (cad == null) continue;
448	      series.add(RideSeriesPoint(time: p.time, value: cad.toDouble()));
449	      if (cad > 0) {
450	        sum += cad;
451	        n++;
452	      }
453	      if (cad > maxV) maxV = cad;
454	    }
455	    if (series.isEmpty) {
456	      return (avg: null, max: null, points: const []);
457	    }
458	    return (
459	      avg: n > 0 ? (sum / n).round() : null,
460	      max: maxV,
461	      points: series,
462	    );
463	  }
