465	  /// 功率序列与统计。口径与踏频刻意不同：`0 W` 是真实样本，计入平均。
466	  static ({double? avg, double? max, List<RideSeriesPoint> points})
467	      _powerSeries(List<_GpxPt> pts) {
468	    final series = <RideSeriesPoint>[];
469	    var sum = 0.0;
470	    var maxV = 0.0;
471	    for (final p in pts) {
472	      final pw = p.pw;
473	      if (pw == null) continue;
474	      series.add(RideSeriesPoint(time: p.time, value: pw.toDouble()));
475	      sum += pw;
476	      if (pw > maxV) maxV = pw.toDouble();
477	    }
478	    if (series.isEmpty) {
479	      return (avg: null, max: null, points: const []);
480	    }
481	    return (avg: sum / series.length, max: maxV, points: series);
482	  }
