484	  static ({double? gain, double? loss, double? min, double? max}) _elev(
485	    List<_GpxPt> pts,
486	  ) {
487	    double? minV;
488	    double? maxV;
489	    var gain = 0.0;
490	    var loss = 0.0;
491	    double? prev;
492	    var n = 0;
493	    for (final p in pts) {
494	      final e = p.ele;
495	      if (e == null) continue;
496	      n++;
497	      minV = minV == null ? e : math.min(minV, e);
498	      maxV = maxV == null ? e : math.max(maxV, e);
499	      if (prev != null) {
500	        final d = e - prev;
501	        if (d > 0.8) gain += d;
502	        if (d < -0.8) loss += -d;
503	      }
504	      prev = e;
505	    }
506	    if (n < 2) {
507	      return (gain: null, loss: null, min: minV, max: maxV);
508	    }
509	    return (
510	      gain: gain > 0.5 ? gain : null,
511	      loss: loss > 0.5 ? loss : null,
512	      min: minV,
513	      max: maxV,
514	    );
515	  }
