517	  /// `1:33:20` 或不足一小时 `33:20`。
518	  static String formatElapsed(Duration d) {
519	    final h = d.inHours;
520	    final m = d.inMinutes.remainder(60).toString().padLeft(2, '0');
521	    final s = d.inSeconds.remainder(60).toString().padLeft(2, '0');
522	    if (h > 0) return '$h:$m:$s';
523	    return '$m:$s';
524	  }
