534	  /// `2024/8/31 09:49`
535	  static String formatStamp(DateTime t) {
536	    final l = t.toLocal();
537	    final hh = l.hour.toString().padLeft(2, '0');
538	    final mm = l.minute.toString().padLeft(2, '0');
539	    return '${l.year}/${l.month}/${l.day} $hh:$mm';
540	  }
