542	  /// 心率区间累计（热身 / 燃脂 / 有氧 / 无氧 / 极限）。
543	  static List<Duration> hrZoneDurations(
544	    List<RideSeriesPoint> pts, {
545	    Duration? total,
546	  }) {
547	    final zones = List<Duration>.filled(5, Duration.zero);
548	    if (pts.isEmpty) return zones;
549	    final fallbackMs =
550	        (total?.inMilliseconds ?? pts.length * 1000) ~/ pts.length;
551	    for (var i = 0; i < pts.length; i++) {
552	      var ms = fallbackMs;
553	      if (i + 1 < pts.length) {
554	        final a = pts[i].time;
555	        final b = pts[i + 1].time;
556	        if (a != null && b != null) {
557	          final d = b.difference(a).inMilliseconds;
558	          if (d > 0 && d <= 120000) ms = d;
559	        }
560	      }
561	      if (ms <= 0) continue;
562	      final z = hrZoneIndex(pts[i].value.round());
563	      zones[z] += Duration(milliseconds: ms);
564	    }
565	    return zones;
566	  }
