568	  /// 按默认最大心率 190 的五区。
569	  static int hrZoneIndex(int bpm) {
570	    if (bpm < 114) return 0;
571	    if (bpm < 133) return 1;
572	    if (bpm < 152) return 2;
573	    if (bpm < 171) return 3;
574	    return 4;
575	  }
