577	  /// 无热量字段时的估算：有心率用 Keytel 简化，否则按里程。
578	  static int estimateKcal({
579	    int? avgHrBpm,
580	    Duration? duration,
581	    double distanceKm = 0,
582	  }) {
583	    final minutes = (duration?.inSeconds ?? 0) / 60.0;
584	    if (avgHrBpm != null && avgHrBpm > 0 && minutes > 0) {
585	      return math.max(1, (avgHrBpm * minutes * 0.03).round());
586	    }
587	    if (distanceKm > 0.001) {
588	      return math.max(1, (distanceKm * 30).round());
589	    }
590	    return 0;
591	  }
