633	  /// 相邻点球面距离之和，千米。
634	  static double distanceKm(List<LatLng> points) {
635	    var sum = 0.0;
636	    for (var i = 1; i < points.length; i++) {
637	      sum += _haversineKm(points[i - 1], points[i]);
638	    }
639	    return sum;
640	  }
641	
642	  static double _haversineKm(LatLng a, LatLng b) {
643	    const r = 6371.0;
644	    final dLat = _rad(b.latitude - a.latitude);
645	    final dLon = _rad(b.longitude - a.longitude);
646	    final x = math.sin(dLat / 2) * math.sin(dLat / 2) +
647	        math.cos(_rad(a.latitude)) *
648	            math.cos(_rad(b.latitude)) *
649	            math.sin(dLon / 2) *
650	            math.sin(dLon / 2);
651	    return 2 * r * math.asin(math.min(1, math.sqrt(x)));
652	  }
653	
654	  static double _rad(double deg) => deg * math.pi / 180;
