656	  /// 列表缩略图用：保留起终点，中间均匀抽点。
657	  static List<LatLng> previewTrack(List<LatLng> points, {int max = 48}) {
658	    if (points.length <= 2) return List<LatLng>.from(points);
659	    if (points.length <= max) return List<LatLng>.from(points);
660	    final last = points.length - 1;
661	    final out = <LatLng>[];
662	    for (var i = 0; i < max; i++) {
663	      final idx = ((last * i) / (max - 1)).round();
664	      if (out.isEmpty || out.last != points[idx]) {
665	        out.add(points[idx]);
666	      }
667	    }
668	    if (out.last != points.last) out.add(points.last);
669	    return out;
670	  }
