745	  /// 码表 FS 的 mtime 不可信。文件里若没有可信 `<time>`，用手机时钟补上。
746	  /// 已有 GNSS/App 时间则原样返回，不改 ele / 扩展字段。
747	  static String ensureTimestamps(String xml, {DateTime? nowUtc}) {
748	    if (plausibleTimes(xml).isNotEmpty) {
749	      return xml;
750	    }
751	    final now = (nowUtc ?? DateTime.now()).toUtc();
752	    var n = _trkptRe.allMatches(xml).length;
753	    if (n == 0) {
754	      n = _trkptSelfRe.allMatches(xml).length;
755	    }
756	    final start = n <= 1 ? now : now.subtract(Duration(seconds: n - 1));
757	    var out = _stampTrkpts(xml, now);
758	    out = _ensureMetadataTime(out, start);
759	    return out;
760	  }
761	
762	  static String _stampTrkpts(String xml, DateTime endUtc) {
763	    final blocks = _trkptRe.allMatches(xml).toList();
764	    if (blocks.isEmpty) {
765	      return _stampSelfClosing(xml, endUtc);
766	    }
767	    final n = blocks.length;
768	    final start = n <= 1
769	        ? endUtc
770	        : endUtc.subtract(Duration(seconds: n - 1));
771	    var out = xml;
772	    for (var i = n - 1; i >= 0; i--) {
773	      final m = blocks[i];
774	      final t = formatUtc(start.add(Duration(seconds: i)));
775	      out = out.replaceRange(m.start, m.end, _stampOneTrkpt(m.group(0)!, t));
776	    }
777	    return out;
778	  }
779	
780	  static String _stampSelfClosing(String xml, DateTime endUtc) {
781	    final blocks = _trkptSelfRe.allMatches(xml).toList();
782	    if (blocks.isEmpty) return xml;
783	    final n = blocks.length;
784	    final start = n <= 1
785	        ? endUtc
786	        : endUtc.subtract(Duration(seconds: n - 1));
787	    var out = xml;
788	    for (var i = n - 1; i >= 0; i--) {
789	      final m = blocks[i];
790	      final attrs = m.group(1) ?? '';
791	      final t = formatUtc(start.add(Duration(seconds: i)));
792	      out = out.replaceRange(
793	        m.start,
794	        m.end,
795	        '<trkpt$attrs><time>$t</time></trkpt>',
796	      );
797	    }
798	    return out;
799	  }
