801	  static String _stampOneTrkpt(String block, String iso) {
802	    if (_timeRe.hasMatch(block)) {
803	      return block.replaceFirst(_timeRe, '<time>$iso</time>');
804	    }
805	    return block.replaceFirst(
806	      RegExp(r'</trkpt>', caseSensitive: false),
807	      '<time>$iso</time></trkpt>',
808	    );
809	  }
