811	  static String _ensureMetadataTime(String xml, DateTime t) {
812	    final iso = formatUtc(t);
813	    final meta = _metaOpenRe.firstMatch(xml);
814	    if (meta != null) {
815	      final closeIdx = xml.toLowerCase().indexOf('</metadata>', meta.end);
816	      if (closeIdx > meta.end) {
817	        final inner = xml.substring(meta.end, closeIdx);
818	        if (_timeRe.hasMatch(inner)) {
819	          final stamped = inner.replaceFirst(_timeRe, '<time>$iso</time>');
820	          return xml.substring(0, meta.end) + stamped + xml.substring(closeIdx);
821	        }
822	        return '${xml.substring(0, meta.end)}<time>$iso</time>${xml.substring(meta.end)}';
823	      }
824	    }
825	    final gpx = _gpxOpenRe.firstMatch(xml);
826	    if (gpx == null) return xml;
827	    return '${xml.substring(0, gpx.end)}\n'
828	        '  <metadata><time>$iso</time></metadata>'
829	        '${xml.substring(gpx.end)}';
830	  }
