850	  /// 码表列表文件名上限约 31 字符（含 .gpx）。
851	  static String safeFileName(String raw, {int maxChars = 31}) {
852	    var stem = raw.trim();
853	    if (stem.toLowerCase().endsWith('.gpx')) {
854	      stem = stem.substring(0, stem.length - 4);
855	    }
856	    final buf = StringBuffer();
857	    for (final r in stem.runes) {
858	      final c = String.fromCharCode(r);
859	      if (RegExp(r'[A-Za-z0-9._\u4e00-\u9fff-]').hasMatch(c)) {
860	        buf.write(c);
861	      } else if (c == ' ') {
862	        buf.write('_');
863	      }
864	    }
865	    var out = buf.toString();
866	    if (out.isEmpty) {
867	      out = 'route';
868	    }
869	    const ext = '.gpx';
870	    final cap = maxChars - ext.length;
871	    if (out.length > cap) {
872	      out = out.substring(0, cap);
873	    }
874	    return '$out$ext';
875	  }
