879	    var stem = raw.trim();
880	    if (stem.toLowerCase().endsWith('.tsv')) {
881	      stem = stem.substring(0, stem.length - 4);
882	    }
883	    final buf = StringBuffer();
884	    for (final r in stem.runes) {
885	      final c = String.fromCharCode(r);
886	      if (RegExp(r'[A-Za-z0-9._\u4e00-\u9fff-]').hasMatch(c)) {
887	        buf.write(c);
888	      } else if (c == ' ') {
889	        buf.write('_');
890	      }
891	    }
892	    var out = buf.toString();
893	    if (out.isEmpty) {
894	      out = 'route';
895	    }
896	    const ext = '.tsv';
897	    final cap = maxChars - ext.length;
898	    out = WaypointTsv.capUtf8(out, cap > 1 ? cap : 1);
899	    return '$out$ext';
900	  }
