199	  /// 重播：底栏读数跟着游标从头走。
200	  ///
201	  /// 先 `forward` 再置播放态：`forward(from: 0)` 会把进度拉回下界，状态机
202	  /// 在这一步同步经过 dismissed，播放态放在它之后建立才不会被重置动作影响。
203	  void _restartPlayback() {
204	    if (_disp.length < 2) return;
205	    _hudTick = 0;
206	    _play.forward(from: 0);
207	    setState(() => _playing = true);
208	    _liveHud.value = _liveAt(0);
209	  }
