211	  /// 当前画到的小数下标（4.5 表示在第 4、5 点之间）。
212	  double get _playCut {
213	    if (_disp.length < 2) return 0;
214	    // 没有速度信息 → 没有时间轴，按点数均匀播。
215	    if (_rideT.length != _disp.length || _rideTotal <= 0) {
216	      return _play.value * (_disp.length - 1);
217	    }
218	    final sec = _play.value * _rideTotal;
219	    // 播完就整条。二进制查找找的是「第一个 >= sec 的下标」，如果尾部有一串
220	    // 零位移点（原地停留，累计时间相同）会停在那串的第一个上，线就画不到底、
221	    // 游标也不消失。
222	    if (sec >= _rideTotal) return _disp.length - 1;
223	    var lo = 0;
224	    var hi = _rideT.length - 1;
225	    while (lo < hi) {
226	      final mid = (lo + hi) >> 1;
227	      if (_rideT[mid] < sec) {
228	        lo = mid + 1;
229	      } else {
230	        hi = mid;
231	      }
232	    }
233	    final i = lo < 1 ? 1 : lo;
234	    final t0 = _rideT[i - 1];
235	    final t1 = _rideT[i];
236	    final f = t1 - t0 <= 0 ? 1.0 : ((sec - t0) / (t1 - t0)).clamp(0.0, 1.0);
237	    return (i - 1) + f;
238	  }
