120	/// 按记录时间过滤周 / 月 / 全部。
121	abstract class RidePeriodFilter {
122	  static DateTime weekStart(DateTime now) {
123	    final day = DateTime(now.year, now.month, now.day);
124	    return day.subtract(Duration(days: day.weekday - 1));
125	  }
126	
127	  static DateTime monthStart(DateTime now) => DateTime(now.year, now.month, 1);
128	
129	  static bool matches(RideRecord rec, RidePeriod period, DateTime now) {
130	    if (period == RidePeriod.all) return true;
131	    if (rec.mtime <= 0) return false;
132	    final t = DateTime.fromMillisecondsSinceEpoch(rec.mtime * 1000);
133	    final start =
134	        period == RidePeriod.week ? weekStart(now) : monthStart(now);
135	    return !t.isBefore(start);
136	  }
