167	  /// 从磁盘加载。
168	  Future<void> load() async {
169	    await _ensureDir();
170	    _items.clear();
171	    if (!await _indexFile.exists()) return;
172	    try {
173	      final raw = jsonDecode(await _indexFile.readAsString());
174	      if (raw is List) {
175	        for (final e in raw) {
176	          if (e is Map<String, dynamic>) {
177	            _items.add(RideRecord.fromJson(Map<String, Object?>.from(e)));
178	          }
179	        }
180	      }
181	    } catch (_) {
182	      _items.clear();
183	    }
184	    _items.sort((a, b) => b.mtime.compareTo(a.mtime));
185	  }
