201	  /// 写入或覆盖一条本机记录。时间取 GPX `<time>`，不采用码表 FS mtime。
202	  Future<RideRecord> putFile({
203	    required String fileName,
204	    required List<int> bytes,
205	    int? remoteSize,
206	    DateTime? stampUtc,
207	  }) async {
208	    await _ensureDir();
209	    final safe = GpxUtil.safeFileName(fileName);
210	    var xml = GpxUtil.ensureTimestamps(
211	      utf8.decode(bytes, allowMalformed: true),
212	      nowUtc: stampUtc,
213	    );
214	    final prev = find(safe);
215	    final keepName = prev != null &&
216	        prev.userRenamed &&
217	        (prev.displayName?.trim().isNotEmpty ?? false);
218	    if (keepName) {
219	      xml = GpxUtil.setName(xml, prev!.displayName!.trim());
220	    }
221	    final out = utf8.encode(xml);
222	    final file = File(p.join(_dir!.path, safe));
223	    await file.writeAsBytes(out, flush: true);
224	    final sum = GpxUtil.parse(xml);
225	    final when = sum.endTime ?? stampUtc ?? DateTime.now().toUtc();
226	    final rec = RideRecord(
227	      fileName: safe,
228	      localPath: file.path,
229	      size: out.length,
230	      mtime: GpxUtil.unixSeconds(when),
231	      distanceKm: sum.distanceKm,
232	      pointCount: sum.points.length,
233	      durationSec: sum.duration?.inSeconds ?? 0,
234	      preview: GpxUtil.previewTrack(sum.points),
235	      displayName: keepName
236	          ? prev!.displayName!.trim()
237	          : (sum.name.isEmpty ? null : sum.name),
238	      remoteSize: remoteSize,
239	      userRenamed: keepName,
240	    );
241	    _items.removeWhere((e) => e.fileName == safe);
242	    _items.insert(0, rec);
243	    _items.sort((a, b) => b.mtime.compareTo(a.mtime));
244	    await _flush();
